\set ON_ERROR_STOP on
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.medicamentos WHERE id='00000000-0000-4000-8000-000000000104' AND estoque_quantidade=8 AND nome='Synthetic edit' AND macro02_stock_managed) THEN RAISE EXCEPTION 'ADJUSTMENT_POSTIMAGE';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.medicamentos WHERE id='00000000-0000-4000-8000-000000000204' AND estoque_quantidade=13 AND macro02_stock_managed) OR NOT EXISTS(SELECT 1 FROM public.renovacoes WHERE id='00000000-0000-4000-8000-000000000205' AND quantidade=3) OR NOT EXISTS(SELECT 1 FROM public.retiradas WHERE id='00000000-0000-4000-8000-000000000206' AND renovacao_origem_id='00000000-0000-4000-8000-000000000205' AND status='agendada') THEN RAISE EXCEPTION 'ACQUISITION_POSTIMAGE';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.medicamentos WHERE id='00000000-0000-4000-8000-000000000304' AND estoque_quantidade=10 AND estoque_ciclo_id IS NULL AND NOT macro02_stock_managed AND estoque_data_referencia='2026-11-26' AND estoque_unidade_medida='comprimido') OR NOT EXISTS(SELECT 1 FROM public.renovacoes WHERE id='00000000-0000-4000-8000-000000000305' AND quantidade IS NULL AND data_aquisicao='2026-11-26') THEN RAISE EXCEPTION 'UNKNOWN_QUANTITY_POSTIMAGE';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.a1_prescription_links WHERE id='00000000-0000-4000-8000-000000000410' AND renovacao_atual_id='00000000-0000-4000-8000-000000000405') THEN RAISE EXCEPTION 'PRESCRIPTION_LINK_POSTIMAGE';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.medicamentos WHERE id='00000000-0000-4000-8000-000000000504' AND estoque_quantidade=10 AND NOT macro02_stock_managed) OR EXISTS(SELECT 1 FROM public.renovacoes WHERE id='00000000-0000-4000-8000-000000000505') OR EXISTS(SELECT 1 FROM vault_macro02_private.dose_commits WHERE medication_id='00000000-0000-4000-8000-000000000504') OR EXISTS(SELECT 1 FROM vault_macro02_private.compound_commits_r6 WHERE request->'medication_before'->>'id'='00000000-0000-4000-8000-000000000504') THEN RAISE EXCEPTION 'ROLLBACK_NOT_ATOMIC';END IF;
 IF (SELECT count(*) FROM vault_macro02_private.compound_commits_r6)<>5 OR (SELECT count(*) FROM vault_macro02_private.dose_commits)<>3 OR (SELECT count(*) FROM public.medicamentos WHERE id='00000000-0000-4000-8000-000000000604' AND estoque_quantidade=8 AND nome IN ('Synthetic edit','Rival'))<>1 THEN RAISE EXCEPTION 'IDEMPOTENCE_OR_RACE_LEDGER';END IF;
END $$;
\echo MACRO02_COMPOUND_PERSISTENCE_ROLLBACK_IDEMPOTENCE_CONCURRENCY_PASS
